contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount, uint unlockTime, uint collectAmt) public payable {
        require(address(this).balance >= amount);

        (uint balBefore, ) = c.Acc(address(this));
        uint ethBefore = address(c).balance;

        c.Put{value: amount}(unlockTime);

        (uint balAfterPut, uint accUnlock) = c.Acc(address(this));
        assert(balAfterPut == balBefore + amount);
        assert(address(c).balance == ethBefore + amount);
        assert(accUnlock >= unlockTime);

        // Attempting a collect must never decrease the recorded balance
        // unless it fully succeeds; use try/catch to observe revert.
        bool reverted;
        if (collectAmt > 0) {
            try c.Collect(collectAmt) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            reverted = true;
        }

        (uint balFinal, ) = c.Acc(address(this));
        if (reverted) {
            assert(balFinal == balBefore + amount);
        } else {
            // If it succeeded, unlockTime must have passed, so only then can balance drop
            assert(block.timestamp > accUnlock);
            assert(balFinal + collectAmt == balBefore + amount);
        }
    }

    receive() external payable {}
}

